// Independent computer-assisted verification (Kv library), for the paper "Existence of SRB measures
// for some Rossler systems": this program checks the band-merging tangency (c near 4.507); the
// variants generated by make_kv_variant.py check the tangencies near c = 5.7.  Statement verified:
// a quadratic, generically unfolding homoclinic tangency of the
// Poincare map P_c of the Rossler system
//     x' = -(y+z),  y' = x + a y,  z' = b + z (x - c),   a = b = 0.2,
// on the section {x = 0, x' > 0} (coordinates (y,z)), for c in J = [cL, cR].
//
// Method (see README.md): the flow is written in polar coordinates and reparametrised by the
// polar angle, so that P_c is the time-2pi map of a 2pi-periodic non-autonomous system
// (rossler_jet.hpp).  Jets (first / second variational equations) are obtained by forward-mode
// differentiation inside the field.  Sets are affine forms (Kv's kv::affine) propagated with the
// mean-value form; the verified one-step Taylor enclosures are Kv's kv::ode (mv_driver.hpp,
// poincare_jet.hpp).  The formula layer below (Krawczyk, graph transforms, chain rule) is written
// from the paper (Lemmas 4.1-4.5).  No code from the CAPD program is used.
//
// Every quantity printed as an interval is a rigorous enclosure.  Every CHECK must print true.

#include <iostream>
#include <iomanip>
#include <sstream>
#include <string>
#include <vector>
#include <cmath>
#include <chrono>
#include <stdexcept>
#include <limits>
#include "poincare_jet.hpp"

namespace ub = boost::numeric::ublas;
typedef kv::interval<double> itv;
typedef kv::affine<double> aff;

// ------------------------------------------------------------------------------------------
// bookkeeping
// ------------------------------------------------------------------------------------------
static bool ALLOK = true;
static int NCHECK = 0, NFAIL = 0;
static void CHECK(const std::string& name, bool ok) {
	std::cout << "CHECK  " << std::left << std::setw(74) << name << " : " << (ok ? "true" : "FALSE") << std::endl;
	NCHECK++;
	if (!ok) NFAIL++;
	ALLOK = ALLOK && ok;
}
static std::chrono::steady_clock::time_point T_START;
static double elapsed() { return std::chrono::duration<double>(std::chrono::steady_clock::now() - T_START).count(); }

static int ORDER = 20;        // Taylor order of kv::ode
static itv A_PAR, B_PAR;      // enclosures of a = b = 0.2

// ------------------------------------------------------------------------------------------
// interval helpers
// ------------------------------------------------------------------------------------------
static double magn(const itv& x) { return std::max(std::fabs(x.lower()), std::fabs(x.upper())); }
static double migr(const itv& x) {
	if (x.lower() <= 0. && 0. <= x.upper()) return 0.;
	return std::min(std::fabs(x.lower()), std::fabs(x.upper()));
}
static itv sym(double r) { return itv(-r, r); }
static itv symI(const itv& x) { return sym(magn(x)); }
static itv sqrI(const itv& x) { return pow(x, 2); }                   // proper square, >= 0
static bool pos(const itv& x) { return x.lower() > 0.; }
static bool neg(const itv& x) { return x.upper() < 0.; }
static bool inInterior(const itv& x, const itv& y) { return y.lower() < x.lower() && x.upper() < y.upper(); }
static double up(const itv& x) { return x.upper(); }                  // a double >= every element
static std::string S(const itv& x) {
	std::ostringstream o;
	o.precision(17);
	o << "[" << x.lower() << ", " << x.upper() << "]";
	return o.str();
}

struct V2 { itv y, z; };
struct M2 { itv m[2][2]; };
struct A2 { aff y, z; };

static itv det2(const M2& M) { return M.m[0][0] * M.m[1][1] - M.m[0][1] * M.m[1][0]; }
static M2 inv2(const M2& M) {
	itv d = det2(M);
	if (d.lower() <= 0. && 0. <= d.upper()) throw std::runtime_error("inv2: interval determinant contains 0");
	M2 R;
	R.m[0][0] = M.m[1][1] / d;  R.m[0][1] = -M.m[0][1] / d;
	R.m[1][0] = -M.m[1][0] / d; R.m[1][1] = M.m[0][0] / d;
	return R;
}
static V2 mul(const M2& M, const V2& v) {
	V2 r;
	r.y = M.m[0][0] * v.y + M.m[0][1] * v.z;
	r.z = M.m[1][0] * v.y + M.m[1][1] * v.z;
	return r;
}
static A2 mulA(const M2& M, const A2& v) {
	A2 r;
	r.y = M.m[0][0] * v.y + M.m[0][1] * v.z;
	r.z = M.m[1][0] * v.y + M.m[1][1] * v.z;
	return r;
}
static V2 toI(const A2& v) { V2 r; r.y = to_interval(v.y); r.z = to_interval(v.z); return r; }
static V2 add(const V2& a, const V2& b) { V2 r; r.y = a.y + b.y; r.z = a.z + b.z; return r; }
static V2 sub(const V2& a, const V2& b) { V2 r; r.y = a.y - b.y; r.z = a.z - b.z; return r; }
static V2 smul(const itv& s, const V2& a) { V2 r; r.y = s * a.y; r.z = s * a.z; return r; }
static std::string S(const V2& v) { return "(" + S(v.y) + ", " + S(v.z) + ")"; }
static bool inInterior(const V2& a, const V2& b) { return inInterior(a.y, b.y) && inInterior(a.z, b.z); }
static bool subsetV(const V2& a, const V2& b) { return subset(a.y, b.y) && subset(a.z, b.z); }

// ------------------------------------------------------------------------------------------
// data of the problem (non-rigorous inputs: they only choose where to look)
// ------------------------------------------------------------------------------------------
static const double E_[2][2] = {{0.9999996961880596, -0.8077389541129416},
                                {7.795022697815469e-4, -0.5895403141503822}};   // columns e_u, e_s
static double PH[2] = {-6.938698731191516, 0.03606348866252088};                  // approx p_cmid
static const double DPH[2] = {-1.2318423388002486, -0.00664781927076086};         // approx dp/dc
static M2 Ei;                                                                    // enclosure of E^{-1}
static const double EU[2] = {E_[0][0], E_[1][0]}, ES[2] = {E_[0][1], E_[1][1]};

// ------------------------------------------------------------------------------------------
// running the jet system.  Each run is self-contained: the affine noise symbols are reset at
// the beginning, and everything that needs correlation is evaluated inside the run.
// ------------------------------------------------------------------------------------------
template <int NG, int NH, int CSLOT>
struct Run {
	pj::JetState<NG, NH, CSLOT> s;
	mv::Stats st;
	double seconds = 0;
	// initial point (y0,z0), parameter c, seeds dy[k], dz[k] (slot k: d(y0,z0)/dp_k)
	void init(const aff& y0, const aff& z0, const aff& c, const aff* dy, const aff* dz) {
		typedef rj::RosslerJet<NG, NH, CSLOT> F;
		s.x(0) = -y0; s.x(1) = z0; s.x(2) = c;
		for (int k = 0; k < NG; k++) { s.x(F::IG + k) = -dy[k]; s.x(F::IG + NG + k) = dz[k]; }
		for (int m = 0; m < NH; m++) { s.x(F::IH + m) = aff(0.); s.x(F::IH + NH + m) = aff(0.); }
		// D = r - z > 0 at t = 0 (start on the section with x' > 0)
		itv D0 = to_interval(s.x(0) - s.x(1));
		if (!(D0.lower() > 0.)) throw std::runtime_error("initial set not in {x' > 0}");
	}
	void run(int nrev, const std::string& label) {
		auto t0 = std::chrono::steady_clock::now();
		bool ok = pj::iterate(A_PAR, B_PAR, s, nrev, ORDER, st);
		seconds = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
		std::cout << "  [run " << label << ": " << nrev << " revolution(s), state dim " << rj::RosslerJet<NG, NH, CSLOT>::N
		          << ", " << st.steps << " steps, " << std::fixed << std::setprecision(1) << seconds << " s]" << std::endl;
		std::cout << std::defaultfloat << std::setprecision(17);
		if (!ok) throw std::runtime_error("integration failed in run " + label);
	}
	// results in (y,z) coordinates, as affine forms
	A2 value() const { A2 r; r.y = -s.r(); r.z = s.z(); return r; }
	A2 G(int k) const { A2 r; r.y = -s.rg(k); r.z = s.zg(k); return r; }
	A2 H(int m) const { A2 r; r.y = -s.rh(m); r.z = s.zh(m); return r; }
};

static void resetAffine() { aff::maxnum() = 0; }
static aff A(const itv& x) { return aff(x); }          // new noise symbol for an interval
static aff A(double x) { return aff(x); }              // exact constant

// Krawczyk test (Lemma 4.1) on the box Q = q0 + [-ry,ry] x [-rz,rz], parameter interval cI
static bool krawczyk(const itv& cI, double q0y, double q0z, double ry, double rz, V2& K, V2* Qout = nullptr) {
	V2 q0; q0.y = itv(q0y); q0.z = itv(q0z);
	V2 Q; Q.y = q0.y + sym(ry); Q.z = q0.z + sym(rz);
	if (Qout) *Qout = Q;
	// P_c(q0) for c in cI
	resetAffine();
	Run<0, 0, -1> R0;
	R0.init(A(q0y), A(q0z), A(cI), nullptr, nullptr);
	R0.run(1, "Krawczyk P(q0)");
	V2 Pq = toI(R0.value());
	// DP over Q x cI  (seeds = unit vectors)
	resetAffine();
	Run<2, 0, -1> R1;
	aff dy[2] = {A(1.), A(0.)}, dz[2] = {A(0.), A(1.)};
	R1.init(A(Q.y), A(Q.z), A(cI), dy, dz);
	R1.run(1, "Krawczyk DP(Q)");
	M2 DP;
	V2 g0 = toI(R1.G(0)), g1 = toI(R1.G(1));
	DP.m[0][0] = g0.y; DP.m[1][0] = g0.z; DP.m[0][1] = g1.y; DP.m[1][1] = g1.z;
	M2 DF = DP;
	DF.m[0][0] -= 1.; DF.m[1][1] -= 1.;
	// approximate inverse of DF (any matrix is admissible)
	double a = mid(DF.m[0][0]), b = mid(DF.m[0][1]), c = mid(DF.m[1][0]), d = mid(DF.m[1][1]);
	double dt = a * d - b * c;
	M2 C;
	C.m[0][0] = itv(d / dt); C.m[0][1] = itv(-b / dt); C.m[1][0] = itv(-c / dt); C.m[1][1] = itv(a / dt);
	// K = q0 - C (P(q0) - q0) + (I - C DF)(Q - q0)
	M2 IC;
	for (int i = 0; i < 2; i++)
		for (int j = 0; j < 2; j++) {
			itv s = (i == j) ? itv(1.) : itv(0.);
			for (int k = 0; k < 2; k++) s -= C.m[i][k] * DF.m[k][j];
			IC.m[i][j] = s;
		}
	V2 Qm = sub(Q, q0);
	K = add(sub(q0, mul(C, sub(Pq, q0))), mul(IC, Qm));
	std::cout << "    Q = " << S(Q) << "\n    K = " << S(K) << std::endl;
	return inInterior(K, Q);
}

// ------------------------------------------------------------------------------------------
int main(int argc, char** argv) {
	T_START = std::chrono::steady_clock::now();
	std::cout.precision(17);
	std::cout << std::boolalpha;
	try {
		// ---------------- parameters of the proof ----------------
		// optional arguments: Delta, Taylor order, c-shift (the c-shift is only for negative tests:
		// it moves J and the approximate fixed point; with a shift of +-3e-8 check (C) must fail)
		const double cshift = (argc > 3) ? atof(argv[3]) : 0.0;
		const double cmid = 4.50698934631197 + cshift;
		const double epsc = 1e-8;
		PH[0] += DPH[0] * cshift;
		PH[1] += DPH[1] * cshift;
		const double cL = cmid - epsc, cR = cmid + epsc;           // doubles; J = [cL, cR] exactly
		const int N = 15;                                          // iterates from W^u_loc to the tip
		const double sm = 5.3682155586e-4;                         // centre of S
		const double Delta = (argc > 1) ? atof(argv[1]) : 1e-9;    // S = [sm - Delta, sm + Delta] (exact)
		if (argc > 2) ORDER = atoi(argv[2]);
		const double delta_u = 6e-4, rho = 1e-5;                   // W^u_loc chart
		const double ru = 1e-6, rs = 1e-6;                         // W^s_loc chart
		A_PAR = itv(2.) / itv(10.);
		B_PAR = itv(2.) / itv(10.);
		const itv J(cL, cR);
		const itv dcJ = J - itv(cmid);

		std::cout << "Kv " << "0.4.62" << ",  Taylor order " << ORDER << std::endl;
		std::cout << "a, b in " << S(A_PAR) << std::endl;
		std::cout << "J = [cL, cR] with cL = " << std::setprecision(52) << cL << "\n                   cR = " << cR << std::setprecision(17) << std::endl;
		// statement of the theorem as printed in the paper (exact endpoints of J, decimal boxes, bounds)
		const char* THM = "statement";
		const char* QK_dec[4] = {"-6.9386987611", "-6.9386987012", "0.0360634877", "0.0360634896"};   // Q_K: uniqueness box
		const char* Q_dec[4]  = {"-6.9386987439", "-6.9386987185", "0.0360634882", "0.0360634892"};   // Q: location box
		const char* LAMU_dec[2] = {"-1.92148", "-1.92146"};   // stated range of lambda_u
		const char* DET_dec = "0.00000005";                   // stated bound |lambda_u lambda_s| < DET
		if (cshift == 0.0)
			CHECK(std::string(THM) + ": cL, cR are the doubles whose exact expansions are printed in the paper",
			      cL == 4.50698933631197018456759906257502734661102294921875 &&
			      cR == 4.50698935631197006301817964413203299045562744140625);
		else
			std::cout << "NEGATIVE TEST: J shifted by " << cshift << std::endl;
		std::cout << "N = " << N << ",  S = sm +- Delta, sm = " << sm << ", Delta = " << Delta << std::endl;

		// E^{-1}
		{
			M2 Em;
			for (int i = 0; i < 2; i++) for (int j = 0; j < 2; j++) Em.m[i][j] = itv(E_[i][j]);
			Ei = inv2(Em);
		}

		// ======================= (a) fixed point, dp/dc, saddle =======================
		std::cout << "\n=== (a) Fixed point (Krawczyk), dp/dc, saddle ===" << std::endl;
		V2 KJ, KL, KM, KR, QJ;
		bool kJ = krawczyk(J, PH[0], PH[1], 3e-8, 1e-9, KJ, &QJ);
		CHECK("Krawczyk: unique fixed point p_c of P_c in Q, all c in J", kJ);
		auto qc = [&](double c, int i) { return PH[i] + DPH[i] * (c - cmid); };
		bool kL = krawczyk(itv(cL), qc(cL, 0), qc(cL, 1), 1e-11, 1e-11, KL);
		CHECK("Krawczyk: fixed point at c = cL", kL);
		bool kM = krawczyk(itv(cmid), PH[0], PH[1], 1e-11, 1e-11, KM);
		CHECK("Krawczyk: fixed point at c = cmid", kM);
		bool kR = krawczyk(itv(cR), qc(cR, 0), qc(cR, 1), 1e-11, 1e-11, KR);
		CHECK("Krawczyk: fixed point at c = cR", kR);
		CHECK("cL, cmid, cR lie in J", in(cL, J) && in(cmid, J) && in(cR, J));
		// P_c has a unique fixed point in Q_J for every c in J; K_L, K_mid, K_R inside Q_J shows that
		// the fixed points found at cL, cmid, cR are those of the J-branch.
		CHECK("K_L, K_mid, K_R lie in Q_J (same fixed-point branch)", subsetV(KL, QJ) && subsetV(KM, QJ) && subsetV(KR, QJ));
		if (cshift == 0.0) {
			// The theorem states uniqueness of p_c in Q_K and p_c in Q.  Uniqueness follows if Q_K lies in
			// the Krawczyk box Q_J used above; location follows if K_J lies in Q.
			// itv("...") is an outward enclosure of a decimal literal; for "inside the decimal box" the
			// box shrunk by one ulp at each end is used, which lies inside the decimal box.
			const double INF = std::numeric_limits<double>::infinity();
			V2 QKout, Qin, Qo;
			QKout.y = itv(itv(QK_dec[0]).lower(), itv(QK_dec[1]).upper());
			QKout.z = itv(itv(QK_dec[2]).lower(), itv(QK_dec[3]).upper());
			Qo.y = itv(Q_dec[0], Q_dec[1]);
			Qo.z = itv(Q_dec[2], Q_dec[3]);
			Qin.y = itv(std::nextafter(Qo.y.lower(), INF), std::nextafter(Qo.y.upper(), -INF));
			Qin.z = itv(std::nextafter(Qo.z.lower(), INF), std::nextafter(Qo.z.upper(), -INF));
			CHECK(std::string(THM) + ": box Q_K lies in the Krawczyk box (uniqueness)", subsetV(QKout, QJ));
			CHECK(std::string(THM) + ": K_J lies in the box Q (location of p_c)", subsetV(KJ, Qin));
		}
		std::cout << "p_c (c in J)  in " << S(KJ) << "\np_cL          in " << S(KL) << "\np_cmid        in " << S(KM)
		          << "\np_cR          in " << S(KR) << std::endl;

		// dp/dc = -(DP - I)^{-1} d_c P   over K_J x J
		V2 dp;
		{
			resetAffine();
			Run<3, 0, 2> R;
			aff dy[3] = {A(1.), A(0.), A(0.)}, dz[3] = {A(0.), A(1.), A(0.)};
			R.init(A(KJ.y), A(KJ.z), A(J), dy, dz);
			R.run(1, "dp/dc");
			V2 g0 = toI(R.G(0)), g1 = toI(R.G(1)), g2 = toI(R.G(2));
			M2 DF;
			DF.m[0][0] = g0.y - 1.; DF.m[1][0] = g0.z; DF.m[0][1] = g1.y; DF.m[1][1] = g1.z - 1.;
			V2 t = mul(inv2(DF), g2);
			dp.y = -t.y; dp.z = -t.z;
		}
		std::cout << "dp/dc         in " << S(dp) << std::endl;
		// remainder of the affine description of p_c:  p_c = PH + DPH (c - cmid) + R,  R in Rbox
		V2 Rbox;
		Rbox.y = (KM.y - PH[0]) + (dp.y - DPH[0]) * dcJ;
		Rbox.z = (KM.z - PH[1]) + (dp.z - DPH[1]) * dcJ;
		V2 ddp; ddp.y = dp.y - DPH[0]; ddp.z = dp.z - DPH[1];
		V2 deltap = mul(Ei, ddp);                // E^{-1}(p_c' - DPH)
		std::cout << "p_c - PH - DPH (c - cmid) in " << S(Rbox) << std::endl;

		// local derivative at the fixed point:  A0 = E^{-1} DP(p_c) E,  c in a parameter set
		auto A0at = [&](const V2& K, const itv& cI, const std::string& label) {
			resetAffine();
			Run<2, 0, -1> R;
			aff dy[2] = {A(EU[0]), A(ES[0])}, dz[2] = {A(EU[1]), A(ES[1])};
			R.init(A(K.y), A(K.z), A(cI), dy, dz);
			R.run(1, label);
			V2 c0 = toI(mulA(Ei, R.G(0))), c1 = toI(mulA(Ei, R.G(1)));
			M2 A0;
			A0.m[0][0] = c0.y; A0.m[1][0] = c0.z; A0.m[0][1] = c1.y; A0.m[1][1] = c1.z;
			return A0;
		};
		M2 A0 = A0at(KJ, J, "Df(0) on K_J x J");
		std::cout << "Df_c(0) in local coordinates:\n  [[" << S(A0.m[0][0]) << ", " << S(A0.m[0][1]) << "],\n   ["
		          << S(A0.m[1][0]) << ", " << S(A0.m[1][1]) << "]]" << std::endl;
		itv tr = A0.m[0][0] + A0.m[1][1];
		itv dt = det2(A0);
		std::cout << "trace in " << S(tr) << "   det in " << S(dt) << std::endl;
		itv chi1 = 1. - tr + dt, chim1 = 1. + tr + dt;
		std::cout << "chi(1) in " << S(chi1) << "   chi(-1) in " << S(chim1) << std::endl;
		CHECK("saddle: chi(1) > 0 > chi(-1)  (lambda_u < -1 < lambda_s < 1)", pos(chi1) && neg(chim1));
		CHECK("dissipative: |det Df_c(0)| < 1", magn(dt) < 1.);
		if (cshift == 0.0) {
			// |lambda_s| = |det|/|lambda_u| <= |det|/(mig tr - 1) and lambda_u = tr - lambda_s
			itv sb = itv(magn(dt)) / (itv(migr(tr)) - 1.);
			itv lam = tr + itv(-sb.upper(), sb.upper());
			std::cout << "lambda_u in " << S(lam) << std::endl;
			CHECK(std::string(THM) + ": lambda_u in the stated range", neg(tr) &&
			      lam.lower() >= itv(LAMU_dec[0]).upper() && lam.upper() <= itv(LAMU_dec[1]).lower());
			CHECK(std::string(THM) + ": |lambda_u lambda_s| = |det| < stated bound", magn(dt) < itv(DET_dec).lower());
			// Sternberg non-resonance (Remark 3.2 of the paper), for all c in J.  With lambda_u < -1 < lambda_s < 0,
			// a resonance lambda_s = lambda_s^i lambda_u^j or lambda_u = lambda_s^i lambda_u^j (i, j >= 0, i+j >= 2)
			// forces rho := log(1/|lambda_s|) / log|lambda_u| = p/q with integers p, q >= 1, and its order is
			// i+j = p+q+1.  If q*rho contains no integer for q < qfirst, every resonance has q >= qfirst and
			// p >= q*rho_lo, hence order >= qfirst + ceil(qfirst*rho_lo) + 1 =: nres.
			itv disc = tr * tr - 4. * dt;
			itv lu = (tr - sqrt(disc)) / 2.;          // the root < -1
			itv ls = dt / lu;                           // the root in (-1, 0)
			bool roots = pos(disc) && pos(dt) && neg(lu + 1.) && neg(ls) && pos(ls + 1.);
			itv rho = log(itv(1.) / (-ls)) / log(-lu);
			std::cout << "lambda_s in " << S(ls) << "   rho = log(1/|lambda_s|)/log|lambda_u| in " << S(rho) << std::endl;
			const long QMAX = 100000;
			long qfirst = QMAX + 1;
			for (long q = 1; q <= QMAX && roots; q++) {
				itv qr = rho * itv(double(q));
				if (std::ceil(qr.lower()) <= qr.upper()) { qfirst = q; break; }
			}
			double nres = double(qfirst) + std::ceil((itv(double(qfirst)) * rho).lower()) + 1.;
			std::cout << "no resonance of order < " << std::setprecision(10) << nres << std::setprecision(17)
			          << "  (first q with an integer in q*rho: " << qfirst << ")" << std::endl;
			CHECK(std::string(THM) + ": no resonance of order <= 10^3 (Sternberg condition)", roots && nres > 1000.);
		}
		std::cout << "  (det > 0: " << pos(dt) << "; with lambda_u < -1 this gives lambda_s = det/lambda_u in (-1, 0))" << std::endl;
		M2 A0L = A0at(KL, itv(cL), "Df(0) at cL");
		M2 A0R = A0at(KR, itv(cR), "Df(0) at cR");
		std::cout << "  elapsed " << elapsed() << " s" << std::endl;

		// ======================= (b) local unstable manifold, Lemma 4.2 =======================
		std::cout << "\n=== (b) W^u_loc: Lemma 4.2 on B_u = [-" << delta_u << "," << delta_u << "] x [-" << rho << "," << rho << "], c in J ===" << std::endl;
		// derivative enclosures of the local map on (box) x J
		struct LocalDerivs { itv a[2][2]; itv h[2][3]; itv fc[2]; };   // h[i][m]: m = (11),(12),(22)
		auto localDerivs = [&](double du, double dv, const std::string& label) {
			resetAffine();
			Run<3, 3, 2> R;
			aff c = A(J);
			aff Ry = A(Rbox.y), Rz = A(Rbox.z);
			aff u = A(sym(du)), v = A(sym(dv));
			aff y0 = PH[0] + DPH[0] * (c - cmid) + Ry + EU[0] * u + ES[0] * v;
			aff z0 = PH[1] + DPH[1] * (c - cmid) + Rz + EU[1] * u + ES[1] * v;
			aff dy[3] = {A(EU[0]), A(ES[0]), A(DPH[0])}, dz[3] = {A(EU[1]), A(ES[1]), A(DPH[1])};
			R.init(y0, z0, c, dy, dz);
			R.run(1, label);
			LocalDerivs L;
			for (int j = 0; j < 2; j++) {
				V2 col = toI(mulA(Ei, R.G(j)));
				L.a[0][j] = col.y; L.a[1][j] = col.z;
			}
			for (int m = 0; m < 3; m++) {
				V2 hm = toI(mulA(Ei, R.H(m)));
				L.h[0][m] = hm.y; L.h[1][m] = hm.z;
			}
			// d_c f = E^{-1}(G_2 - DPH) + (A - I) E^{-1}(p_c' - DPH)
			A2 g2 = R.G(2);
			g2.y = g2.y - DPH[0]; g2.z = g2.z - DPH[1];
			V2 f0 = toI(mulA(Ei, g2));
			L.fc[0] = f0.y + (L.a[0][0] - 1.) * deltap.y + L.a[0][1] * deltap.z;
			L.fc[1] = f0.z + L.a[1][0] * deltap.y + (L.a[1][1] - 1.) * deltap.z;
			std::cout << "    a = [[" << S(L.a[0][0]) << ", " << S(L.a[0][1]) << "],\n         [" << S(L.a[1][0]) << ", " << S(L.a[1][1]) << "]]\n";
			std::cout << "    h^1 (11,12,22) = " << S(L.h[0][0]) << ", " << S(L.h[0][1]) << ", " << S(L.h[0][2]) << "\n";
			std::cout << "    h^2 (11,12,22) = " << S(L.h[1][0]) << ", " << S(L.h[1][1]) << ", " << S(L.h[1][2]) << "\n";
			std::cout << "    f_c = (" << S(L.fc[0]) << ", " << S(L.fc[1]) << ")" << std::endl;
			return L;
		};
		LocalDerivs LU = localDerivs(delta_u, rho, "W^u box");
		double Lu = 0, Ku = 0, Mu = 0;
		struct WuOut { itv Phi1, Psi1, Phi2, Psi2, wp, wpp, wc, theta; double m, kden; };
		auto wuMaps = [&](double L, double K, double M) {
			WuOut o;
			itv Lw = sym(L), Kw = sym(K), Mw = sym(M);
			o.Phi1 = LU.a[0][0] + LU.a[0][1] * Lw;
			o.Psi1 = LU.a[1][0] + LU.a[1][1] * Lw;
			o.Phi2 = LU.h[0][0] + 2. * LU.h[0][1] * Lw + LU.h[0][2] * itv(0., up(itv(L) * L)) + LU.a[0][1] * Kw;
			o.Psi2 = LU.h[1][0] + 2. * LU.h[1][1] * Lw + LU.h[1][2] * itv(0., up(itv(L) * L)) + LU.a[1][1] * Kw;
			if (zero_in(o.Phi1)) throw std::runtime_error("W^u: Phi1 contains 0");
			o.wp = o.Psi1 / o.Phi1;
			o.wpp = (o.Psi2 * o.Phi1 - o.Psi1 * o.Phi2) / pow(o.Phi1, 3);
			o.wc = LU.fc[1] + LU.a[1][1] * Mw - o.wp * (LU.fc[0] + LU.a[0][1] * Mw);
			// contraction (U6)
			double m = migr(LU.a[0][0]);
			o.m = m;
			itv kden = 1. - itv(magn(LU.a[0][1])) * L / itv(m);
			o.kden = kden.lower();
			itv kappa = (itv(magn(LU.a[0][1])) / itv(m)) / kden;
			o.theta = itv(magn(LU.a[1][0])) * kappa + itv(magn(LU.a[1][1])) * (L * kappa + 1.);
			return o;
		};
		for (int it = 0; it < 40; it++) {    // heuristic search for consistent bounds; verified below
			WuOut o = wuMaps(Lu, Ku, Mu);
			Lu = 1.05 * magn(o.wp) + 1e-14; Ku = 1.05 * magn(o.wpp) + 1e-14; Mu = 1.05 * magn(o.wc) + 1e-14;
		}
		{
			WuOut o = wuMaps(Lu, Ku, Mu);
			std::cout << "W^u bounds: L = " << Lu << "  K = " << Ku << "  M = " << Mu << std::endl;
			std::cout << "    Phi1 in " << S(o.Phi1) << ",  Psi1/Phi1 in " << S(o.wp) << "\n    w'' image in " << S(o.wpp)
			          << ",  dw/dc image in " << S(o.wc) << "\n    theta in " << S(o.theta) << std::endl;
			CHECK("(U1) mig Phi1 > 1", migr(o.Phi1) > 1.);
			CHECK("(U2) L delta <= rho", up(itv(Lu) * delta_u) <= rho);
			CHECK("(U2) mag a21 delta + mag a22 rho <= rho", up(itv(magn(LU.a[1][0])) * delta_u + itv(magn(LU.a[1][1])) * rho) <= rho);
			CHECK("(U3) Psi1/Phi1 in [-L,L]", subset(o.wp, sym(Lu)));
			CHECK("(U4) (Psi2 Phi1 - Psi1 Phi2)/Phi1^3 in [-K,K]", subset(o.wpp, sym(Ku)));
			CHECK("(U5) dw/dc image in [-M,M]", subset(o.wc, sym(Mu)));
			CHECK("(U6) 1 - mag a12 L/m > 0 and theta < 1", o.m > 0. && o.kden > 0. && o.theta.upper() < 1.);
		}
		// Lemma 4.2 (c): slope of W^u_loc at the fixed point
		auto slope0 = [&](const M2& A0x) {
			itv den = A0x.m[0][0] + A0x.m[0][1] * sym(Lu) - A0x.m[1][1];
			if (zero_in(den)) throw std::runtime_error("slope0: denominator contains 0");
			itv t = A0x.m[1][0] / den;
			return t;
		};
		itv tJ = slope0(A0), tL = slope0(A0L), tR = slope0(A0R);
		double t0J = magn(tJ), t0L = magn(tL), t0R = magn(tR);
		std::cout << "|w_c'(0)| <= t0 = " << t0J << " (c in J),  " << t0L << " (c = cL),  " << t0R << " (c = cR)" << std::endl;
		CHECK("Lemma 4.2(c): slope enclosures consistent (|t| <= L)", subset(tJ, sym(Lu)) && subset(tL, sym(Lu)) && subset(tR, sym(Lu)));
		std::cout << "  elapsed " << elapsed() << " s" << std::endl;

		// ======================= (c) local stable manifold, Lemma 4.3 =======================
		std::cout << "\n=== (c) W^s_loc: Lemma 4.3 on B_s = [-" << ru << "," << ru << "] x [-" << rs << "," << rs << "], c in J ===" << std::endl;
		LocalDerivs LS = localDerivs(ru, rs, "W^s box");
		double Ls = 0, Ks = 0, Ms = 0;
		struct WsOut { itv D, Sig1, F, Q1, Q2, spp, sc; };
		auto wsMaps = [&](double L, double K, double M) {
			WsOut o;
			o.D = LS.a[0][0] - sym(L) * LS.a[1][0];
			if (zero_in(o.D)) throw std::runtime_error("W^s: D contains 0");
			o.Sig1 = (sym(L) * LS.a[1][1] - LS.a[0][1]) / o.D;
			double lp = magn(o.Sig1);
			o.F = LS.a[1][0] * sym(lp) + LS.a[1][1];
			itv l2 = itv(0., up(itv(lp) * lp));
			o.Q1 = LS.h[0][0] * l2 + 2. * LS.h[0][1] * sym(lp) + LS.h[0][2];
			o.Q2 = LS.h[1][0] * l2 + 2. * LS.h[1][1] * sym(lp) + LS.h[1][2];
			o.spp = (sym(K) * sqrI(o.F) + sym(L) * o.Q2 - o.Q1) / o.D;
			o.sc = (sym(L) * LS.fc[1] + sym(M) - LS.fc[0]) / o.D;
			return o;
		};
		for (int it = 0; it < 60; it++) {
			WsOut o = wsMaps(Ls, Ks, Ms);
			Ls = 1.05 * magn(o.Sig1) + 1e-14; Ks = 1.05 * magn(o.spp) + 1e-14; Ms = 1.05 * magn(o.sc) + 1e-14;
		}
		{
			WsOut o = wsMaps(Ls, Ks, Ms);
			std::cout << "W^s bounds: Ls = " << Ls << "  Ks = " << Ks << "  Ms = " << Ms << std::endl;
			std::cout << "    D in " << S(o.D) << ",  Sigma1 in " << S(o.Sig1) << "\n    sigma'' image in " << S(o.spp)
			          << ",  dsigma/dc image in " << S(o.sc) << std::endl;
			CHECK("(S1) mag a21 ru + mag a22 rs <= rs", up(itv(magn(LS.a[1][0])) * ru + itv(magn(LS.a[1][1])) * rs) <= rs);
			CHECK("(S2) mig D > 1", migr(o.D) > 1.);
			itv nn = itv(migr(LS.a[0][0])) - itv(Ls) * magn(LS.a[1][0]);
			CHECK("(S3) n = mig a11 - Ls mag a21 > 0 and (mag a12 + Ls mag a22) rs <= n ru",
			      pos(nn) && up((itv(magn(LS.a[0][1])) + itv(Ls) * magn(LS.a[1][1])) * rs) <= (nn * ru).lower());
			CHECK("(S4) Sigma1 in [-Ls,Ls]", subset(o.Sig1, sym(Ls)));
			CHECK("(S5) sigma'' image in [-Ks,Ks]", subset(o.spp, sym(Ks)));
			CHECK("(S6) dsigma/dc image in [-Ms,Ms]", subset(o.sc, sym(Ms)));
			CHECK("(S7) mag a21 Ls + mag a22 < 1", up(itv(magn(LS.a[1][0])) * Ls + magn(LS.a[1][1])) < 1.);
		}
		std::cout << "  elapsed " << elapsed() << " s" << std::endl;

		// ======================= (d) the tangency =======================
		std::cout << "\n=== (d) Tangency function g(s,c) = U - sigma_c(V), N = " << N << " ===" << std::endl;
		const itv Sint = itv(sm) + sym(Delta);                           // contains S
		CHECK("S inside the W^u_loc domain: 0 < sm - Delta, sm + Delta <= delta_u",
		      pos(itv(sm) - itv(Delta)) && up(itv(sm) + itv(Delta)) <= delta_u);
		// |w_c(s)| <= t0 |s| + K s^2/2,  |w_c'(s)| <= t0 + K |s|  (Lemma 4.2(c))
		auto wBound = [&](const itv& s, double t0) { double m = magn(s); return up(itv(t0) * m + itv(Ku) * m * m / 2.); };
		auto wpBound = [&](const itv& s, double t0) { double m = magn(s); return up(itv(t0) + itv(Ku) * m); };

		// generic tip computation.  p_c is described affinely: py, pz (affine forms sharing the
		// noise symbols used in the initial set); s is an affine form; seeds of slot 0 = e_u + w' e_s.
		struct Tip { itv U, V, Us, Vs, Uss, Vss, Uc, Vc; };

		// ---- (C) at c = cL and c = cR (thin points) ----
		itv gL, gsL, gR;
		itv VL, VR;
		{
			resetAffine();
			Run<1, 0, -1> R;
			aff py = A(KL.y), pz = A(KL.z);
			aff w = A(sym(wBound(itv(sm), t0L)));
			aff wp = A(sym(wpBound(itv(sm), t0L)));
			aff y0 = py + EU[0] * sm + ES[0] * w, z0 = pz + EU[1] * sm + ES[1] * w;
			aff dy[1] = {EU[0] + wp * ES[0]}, dz[1] = {EU[1] + wp * ES[1]};
			R.init(y0, z0, A(itv(cL)), dy, dz);
			R.run(N, "(C) at (sm, cL)");
			A2 G = R.value();
			G.y = G.y - py; G.z = G.z - pz;
			V2 UV = toI(mulA(Ei, G));
			V2 UVs = toI(mulA(Ei, R.G(0)));
			VL = UV.z;
			gL = UV.y + sym(Ls) * symI(UV.z);          // U - sigma(V), |sigma(V)| <= Ls |V|
			gsL = UVs.y - sym(Ls) * UVs.z;
			std::cout << "c = cL, s = sm:  U in " << S(UV.y) << "  V in " << S(UV.z) << "\n    g in " << S(gL)
			          << "\n    g_s in " << S(gsL) << std::endl;
		}
		{
			resetAffine();
			Run<0, 0, -1> R;
			aff py = A(KR.y), pz = A(KR.z);
			aff w = A(sym(wBound(itv(sm), t0R)));
			aff y0 = py + EU[0] * sm + ES[0] * w, z0 = pz + EU[1] * sm + ES[1] * w;
			R.init(y0, z0, A(itv(cR)), nullptr, nullptr);
			R.run(N, "(C) at (sm, cR)");
			A2 G = R.value();
			G.y = G.y - py; G.z = G.z - pz;
			V2 UV = toI(mulA(Ei, G));
			VR = UV.z;
			gR = UV.y + sym(Ls) * symI(UV.z);
			std::cout << "c = cR, s = sm:  U in " << S(UV.y) << "  V in " << S(UV.z) << "\n    g in " << S(gR) << std::endl;
		}

		// ---- (B) endpoints of S, c in J ----
		auto endpoint = [&](double sign, const std::string& label) {
			resetAffine();
			Run<1, 0, -1> R;
			aff c = A(J);
			aff py = PH[0] + DPH[0] * (c - cmid) + A(Rbox.y);
			aff pz = PH[1] + DPH[1] * (c - cmid) + A(Rbox.z);
			itv sI = itv(sm) + itv(sign * Delta);                    // contains the exact endpoint
			aff s = A(sI);
			aff w = A(sym(wBound(sI, t0J)));
			aff wp = A(sym(wpBound(sI, t0J)));
			aff y0 = py + EU[0] * s + ES[0] * w, z0 = pz + EU[1] * s + ES[1] * w;
			aff dy[1] = {EU[0] + wp * ES[0]}, dz[1] = {EU[1] + wp * ES[1]};
			R.init(y0, z0, c, dy, dz);
			R.run(N, label);
			A2 G = R.value();
			G.y = G.y - py; G.z = G.z - pz;
			V2 UV = toI(mulA(Ei, G));
			V2 UVs = toI(mulA(Ei, R.G(0)));
			itv gs = UVs.y - sym(Ls) * UVs.z;
			std::cout << label << ":  U in " << S(UV.y) << "  V in " << S(UV.z) << "\n    g_s in " << S(gs) << std::endl;
			return std::make_pair(gs, UV.z);
		};
		auto Bm = endpoint(-1., "(B) s = sm - Delta, c in J");
		auto Bp = endpoint(+1., "(B) s = sm + Delta, c in J");

		// ---- (A) second derivative on S x J ----
		itv gss, VA;
		{
			resetAffine();
			Run<2, 1, -1> R;
			aff c = A(J);
			aff py = PH[0] + DPH[0] * (c - cmid) + A(Rbox.y);
			aff pz = PH[1] + DPH[1] * (c - cmid) + A(Rbox.z);
			aff s = sm + A(sym(Delta));
			aff w = A(sym(wBound(Sint, t0J)));
			aff wp = A(sym(wpBound(Sint, t0J)));
			aff y0 = py + EU[0] * s + ES[0] * w, z0 = pz + EU[1] * s + ES[1] * w;
			aff dy[2] = {EU[0] + wp * ES[0], A(ES[0])}, dz[2] = {EU[1] + wp * ES[1], A(ES[1])};
			R.init(y0, z0, c, dy, dz);
			R.run(N, "(A) on S x J");
			A2 G = R.value();
			G.y = G.y - py; G.z = G.z - pz;
			V2 UV = toI(mulA(Ei, G));
			V2 UVs = toI(mulA(Ei, R.G(0)));
			// Gamma_ss = H_N[d1,d1] + w'' D_N e_s,  |w''| <= K
			A2 Hss = R.H(0);
			A2 G1 = R.G(1);
			aff wpp = A(sym(Ku));
			Hss.y = Hss.y + wpp * G1.y; Hss.z = Hss.z + wpp * G1.z;
			V2 UVss = toI(mulA(Ei, Hss));
			VA = UV.z;
			gss = UVss.y - sym(Ks) * sqrI(UVs.z) - sym(Ls) * UVss.z;
			std::cout << "(A) on S x J:  U in " << S(UV.y) << "  V in " << S(UV.z) << "\n    (U_s, V_s) in " << S(UVs)
			          << "\n    (U_ss, V_ss) in " << S(UVss) << "\n    g_ss in " << S(gss) << std::endl;
		}

		// ---- (D) parameter derivative on S x J ----
		itv gc, VD;
		{
			resetAffine();
			Run<3, 0, 2> R;
			aff c = A(J);
			aff py = PH[0] + DPH[0] * (c - cmid) + A(Rbox.y);
			aff pz = PH[1] + DPH[1] * (c - cmid) + A(Rbox.z);
			aff s = sm + A(sym(Delta));
			itv WP = sym(wpBound(Sint, t0J));
			aff w = A(sym(wBound(Sint, t0J)));
			aff wp = A(WP);
			aff y0 = py + EU[0] * s + ES[0] * w, z0 = pz + EU[1] * s + ES[1] * w;
			aff dy[3] = {EU[0] + wp * ES[0], A(ES[0]), A(DPH[0])}, dz[3] = {EU[1] + wp * ES[1], A(ES[1]), A(DPH[1])};
			R.init(y0, z0, c, dy, dz);
			R.run(N, "(D) on S x J");
			A2 G = R.value();
			G.y = G.y - py; G.z = G.z - pz;
			V2 UV = toI(mulA(Ei, G));
			// (U_c,V_c) = E^{-1}(G_2 - DPH) + E^{-1}(D_N e_u) deltap_1 + E^{-1}(D_N e_s)(deltap_2 + d_c w) - deltap
			A2 g2 = R.G(2);
			g2.y = g2.y - DPH[0]; g2.z = g2.z - DPH[1];
			V2 T0 = toI(mulA(Ei, g2));
			V2 Es = toI(mulA(Ei, R.G(1)));                     // E^{-1} D_N e_s
			V2 Eu = sub(toI(mulA(Ei, R.G(0))), smul(WP, Es));   // E^{-1} D_N e_u, since G_0 = D_N(e_u + w' e_s)
			itv cw = sym(Mu);
			V2 UVc = sub(add(add(T0, smul(deltap.y, Eu)), smul(deltap.z + cw, Es)), deltap);
			VD = UV.z;
			gc = UVc.y - sym(Ms) - sym(Ls) * UVc.z;
			std::cout << "(D) on S x J:  U in " << S(UV.y) << "  V in " << S(UV.z) << "\n    E^{-1}D_N e_u in " << S(Eu)
			          << "\n    E^{-1}D_N e_s in " << S(Es) << "\n    (U_c, V_c) in " << S(UVc) << "\n    g_c in " << S(gc) << std::endl;
		}

		// ---- the four conditions of Lemma 4.5 ----
		std::cout << "\n--- Lemma 4.5 ---" << std::endl;
		CHECK("chart: |V| <= rs on S x J (from run A) and (from run D)", subset(VA, sym(rs)) && subset(VD, sym(rs)));
		CHECK("chart: |V| <= rs at the S endpoints x J and at (sm,cL), (sm,cR)",
		      subset(Bm.second, sym(rs)) && subset(Bp.second, sym(rs)) && subset(VL, sym(rs)) && subset(VR, sym(rs)));
		CHECK("(A) d^2g/ds^2 < 0 on S x J", neg(gss));
		CHECK("(B) dg/ds(sm - Delta, c) > 0 for all c in J", pos(Bm.first));
		CHECK("(B) dg/ds(sm + Delta, c) < 0 for all c in J", neg(Bp.first));
		double gamma = migr(gss);   // g_ss <= -gamma on S x J, in particular on S x {cL}
		itv supL = gL + sqrI(itv(magn(gsL))) / (2. * itv(gamma));
		std::cout << "gamma = min|g_ss| >= " << gamma << ";  sup_S g(., cL) <= g(sm,cL) + g_s(sm,cL)^2/(2 gamma) <= " << supL.upper() << std::endl;
		CHECK("(C) g(s,cL) < 0 for all s in S  (Taylor bound, Remark 4.6)", neg(gss) && neg(supL));
		CHECK("(C) g(sm,cR) > 0", pos(gR));
		CHECK("(D) dg/dc > 0 on S x J", pos(gc));

		std::cout << "\nSummary of key enclosures:" << std::endl;
		std::cout << "  g(sm,cL) in " << S(gL) << ",  g(sm,cR) in " << S(gR) << std::endl;
		std::cout << "  g_s(sm-Delta,J) in " << S(Bm.first) << ",  g_s(sm+Delta,J) in " << S(Bp.first) << std::endl;
		std::cout << "  g_ss(S x J) in " << S(gss) << ",  g_c(S x J) in " << S(gc) << std::endl;
		std::cout << "\nchecks: " << NCHECK << ", failed: " << NFAIL << ",  total time " << elapsed() << " s" << std::endl;
		std::cout << "ALL CHECKS PASSED: " << ALLOK << std::endl;
	} catch (std::exception& e) {
		std::cout << "\nException: " << e.what() << std::endl;
		std::cout << "ALL CHECKS PASSED: false" << std::endl;
		return 1;
	}
	return ALLOK ? 0 : 2;
}
